#!/usr/bin/env bash
# Exports the IDLs (and the TypeScript types) generated by `anchor build` to solana/idls/, the
# checked-in interface for indexers and clients. `tests/tests/idl_export.rs` fails when they drift.
set -euo pipefail
cd "$(dirname "$0")/.."
mkdir -p idls/types
for p in merces_registry merces_hook merces_protocol mock_usdg_hook; do
  cp "target/idl/$p.json" "idls/$p.json"
  cp "target/types/$p.ts" "idls/types/$p.ts"
done
echo "exported IDLs to solana/idls/"
